{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — should I maximize total profit (unit price minus raw material cost, with the operating costs treated as fixed full-capacity charges that do not depend on how much each machine is used), or should I maximize total revenue, or minimize total cost?"
  ],
  "rationale": "The response asks for a single policy choice among three mutually exclusive objective functions, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there a demand limit on how many units of each product can be sold (i.e., an upper bound on the quantity produced and sold of each product), or can the factory produce and sell unlimited quantities of each product as long as machine hours allow?"
  ],
  "rationale": "The response asks a single clarification question regarding whether there is an upper bound on production/sales or if it is unlimited, which constitutes one independent policy choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each product, must the quantity that goes through procedure A exactly equal the quantity that goes through procedure B (i.e., every unit produced must complete both procedures, with no work-in-progress left over at the end of the period), or is it acceptable to have unequal amounts in the two procedures?"
  ],
  "rationale": "The response asks a single clarification question regarding the relationship between quantities in two procedures, presenting a binary choice (equal vs. unequal) which constitutes one independent semantic request."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Does this mean that if a machine is used for even one hour, the full listed cost is incurred (e.g., using A1 for just 1 hour still costs 300 yuan), or is the cost proportional to the fraction of capacity actually used?"
  ],
  "rationale": "The response asks for a single policy choice regarding how operating costs are calculated (fixed vs. proportional), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Since the operating cost is a fixed charge paid whenever a machine is used at all, should the model be allowed to choose not to operate a machine (thereby paying zero cost for it), or must every machine be operated in the plan regardless of whether it is needed?"
  ],
  "rationale": "The response asks for a single policy decision regarding whether machines can be left idle or must all be operated."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a single product's units be split across multiple machines within the same procedure (for example, some units of Product I processed on A1 and the rest on A2), or must each product be assigned to exactly one machine per procedure?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether product units can be split across machines or must be assigned to one machine, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Should the production quantities of the three products be required to be whole numbers (integer units), or is it acceptable for them to be fractional values?"
  ],
  "rationale": "The response asks a single clarification question regarding the integrality constraint for production quantities."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is this the maximum total processing time that can be assigned to that machine in the plan, meaning the sum of all processing times on that machine must not exceed this value?"
  ],
  "rationale": "The response asks a single clarification question regarding the definition of 'Effective Machine Hours' as a capacity constraint."
}

